from taf.internal.aliasing import aliasing_scope
from taf.analyzer.aasyslog_throughput.throughput import Throughput
from taf.analyzer.aasyslog_throughput.facade import AasyslogThroughput


class aasyslog_throughput(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(lookup_arg='throughput',
                                           lookup_type=Throughput)

    def create_uplink_throughput(self, cells=None, log=None, throughput_records_output=None, alias=None):
        """
        Create uplink throughput instance.

        :param cells: (optional) nrCellId list for checking throughput
        :type cells: list[Union[str, int]]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path or a dict object
        :type throughput_records_output: Union[str, dict]
        :param alias: (optional) alias for the new Throughput class instance, default is None
        :type alias: str
        :return: Throughput class instance
        """
        cells = [str(cell) for cell in cells] if cells else None
        throughput = AasyslogThroughput.create_uplink_throughput(cells, log, throughput_records_output)
        self.store.add(throughput, alias)
        return throughput

    def create_downlink_throughput(self, cells=None, log=None, throughput_records_output=None, alias=None):
        """
        Create downlink throughput instance.

        :param cells: (optional) nrCellId list for checking throughput
        :type cells: list[Union[str, int]]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path or a dict object
        :type throughput_records_output: Union[str, dict]
        :param alias: (optional) alias for the new Throughput class instance, default is None
        :type alias: str
        :return: Throughput class instance
        """
        cells = [str(cell) for cell in cells] if cells else None
        throughput = AasyslogThroughput.create_downlink_throughput(cells, log, throughput_records_output)
        self.store.add(throughput, alias)
        return throughput

    def create_ca_downlink_throughput(self, cells, log=None, throughput_records_output=None, alias=None):
        """
        Create Carrier Aggregation uplink throughput instance.

        :param cells: nrCellId list for checking throughput
        :type cells: list[Union[str, int]]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path or a dict object
        :type throughput_records_output: Union[str, dict]
        :param alias: (optional) alias for the new Throughput class instance, default is None
        :type alias: str
        :return: Throughput class instance
        """
        cells = [str(cell) for cell in cells] if cells else None
        throughput = AasyslogThroughput.create_ca_downlink_throughput(cells, log, throughput_records_output)
        self.store.add(throughput, alias)
        return throughput

    def create_ca_uplink_throughput(self, cells, log=None, throughput_records_output=None, alias=None):
        """
        Create Carrier Aggregation downlink throughput instance.

        :param cells: nrCellId list for checking throughput
        :type cells: list[Union[str, int]]
        :param log: (optional) aasyslog file path
        :type log: str
        :param throughput_records_output: (optional) throughput records output file path or a dict object
        :type throughput_records_output: Union[str, dict]
        :param alias: (optional) alias for the new Throughput class instance, default is None
        :type alias: str
        :return: Throughput class instance
        """
        cells = [str(cell) for cell in cells] if cells else None
        throughput = AasyslogThroughput.create_ca_uplink_throughput(cells, log, throughput_records_output)
        self.store.add(throughput, alias)
        return throughput

    def analyze(self, throughputs, log=None):
        """
        Analyze and calculate throughput.

        :param throughputs: alias list for the Throughput class instance
        :type cells: list[str]
        :param log: (optional) aasyslog file path shared in throughputs,
        the log in create_xxx_xxx_throughput will be ignored when it is set
        :type log: str
        :return: None
        """
        throughput_instances = [self.store.get(alias) for alias in throughputs]
        AasyslogThroughput.analyze(throughput_instances, log)

    @lookup_handler.implicit_lookup
    def get_throughput(self, throughput=None):
        """
        Get the calculated throughput result.

        :param throughput: alias for the Throughput class instance
        :type throughput: str
        :return: List[dict] for the calculated throughput result, throughput unit is Mbit/sec
        """
        return [item.to_dict() for item in AasyslogThroughput.get_throughput(throughput)]
